(()=>{'use strict';const root=document.getElementById('av-services-slider');if(!root)return;const track=root.querySelector('.sv-track'),cards=[...root.querySelectorAll('.sv-card')],prev=root.querySelector('[data-sv-prev]'),next=root.querySelector('[data-sv-next]'),count=root.querySelector('.sv-count');let index=0,frame;const update=()=>{let d=Infinity;cards.forEach((c,i)=>{let n=Math.abs(c.getBoundingClientRect().left-track.getBoundingClientRect().left-parseFloat(getComputedStyle(track).paddingLeft));if(n<d){d=n;index=i}});count.textContent=(index+1)+' / '+cards.length;prev.disabled=track.scrollLeft<2;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-2};const go=dir=>{const c=cards[Math.max(0,Math.min(cards.length-1,index+dir))];track.scrollTo({left:c.offsetLeft-track.offsetLeft-parseFloat(getComputedStyle(track).paddingLeft),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};prev.addEventListener('click',()=>go(-1));next.addEventListener('click',()=>go(1));track.addEventListener('scroll',()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(update)},{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(e.key==='ArrowRight'?1:-1)}});window.addEventListener('resize',update);update()})();